-- Mini MES 로컬 제조 데모. 대상: MySQL80 / 127.0.0.1:3306 / mini_mes.
-- 실행: mysql --no-defaults --protocol=TCP -h 127.0.0.1 -P 3306 -u <계정> -p --database=mini_mes --default-character-set=utf8mb4 --batch < db/demo-seed.sql
-- 비밀번호는 프롬프트/프로세스 환경으로만 전달. 파일/명령 인수에 기록하지 않는다.
-- 반드시 TCP 수신 프로세스가 MySQL80 서비스 소속임을 먼저 확인한다.
-- --force 및 대화형 SOURCE 금지: batch 오류 시 즉시 종료/연결 종료로 미커밋 전체 롤백.
-- DEMO 데이터가 하나라도 있으면 전체/부분 여부와 무관하게 중단한다. 재실행은 추가 INSERT 없음.
-- 기존 행 UPDATE/DELETE, DDL, 임시 테이블/프로시저 생성, 제약 비활성화 없음.
-- 아래는 과거 제조 흐름의 최종 스냅샷이다. 실제 상태 전이 API를 실행한 기록은 아니다.
-- READY→IN_PROGRESS→COMPLETED 및 READY→CANCELLED에 맞는 시각/담당자를 INSERT한다.
-- 원장/Receipt/정정 이력과 최종 재고를 한 트랜잭션에 INSERT하며 업무 Service는 검증하지 않는다.
-- 명시 PK는 실행 시 각 테이블 MAX+오프셋. 동시 다른 쓰기 충돌은 덮어쓰기 없이 전체 실패한다.
-- 식별자: DEMO-TEMP-20261029 / 코드·LOT 번호 DEMO- 접두사. 시각은 UTC, 수량은 모두 EA 정수.
-- 최초 실적 Receipt는 원래 성공값 60/57/3, 현재 실적은 정정 후 60/55/5이다.
-- ID 산술식은 UNSIGNED로 명시 변환한다. MySQL 사용자 변수의 DECIMAL 문자열이 fingerprint에 유입되지 않도록 한다.
-- 표준 V2의 케이블 소요량은 2, 실제 생산은 당시 V1(1)을 사용하여 과거 연결을 보여준다.
SET NAMES utf8mb4;
SET SESSION time_zone='+00:00';
SET SESSION innodb_lock_wait_timeout=5;
SELECT IF((DATABASE()='mini_mes' AND @@port=3306 AND @@server_uuid='65cf4d2d-ce9a-11f1-8ab9-04421a255760' AND REPLACE(@@datadir,CHAR(92),'/')='C:/ProgramData/MySQL/MySQL Server 8.0/Data/'),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: wrong local server/database','$')) AS seed_guard;
SELECT IF((FIND_IN_SET('STRICT_TRANS_TABLES',@@sql_mode)>0 OR FIND_IN_SET('STRICT_ALL_TABLES',@@sql_mode)>0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: strict mode required','$')) AS seed_guard;
SELECT IF((@@foreign_key_checks=1 AND @@unique_checks=1 AND NOT EXISTS(SELECT 1 FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA='mini_mes' AND CONSTRAINT_TYPE='CHECK' AND ENFORCED<>'YES')),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: constraints must stay enabled','$')) AS seed_guard;
SELECT IF((GET_LOCK('mini_mes.DEMO-TEMP-20261029',0)=1),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: another seed session is active','$')) AS seed_guard;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
START TRANSACTION;
SET @demo_actor='DEMO-TEMP-20261029';
SELECT IF(((SELECT SUM(demo_count) FROM (SELECT 'item' table_name,COUNT(*) demo_count FROM item WHERE created_by LIKE 'DEMO%'  OR item_code LIKE 'DEMO%'  UNION ALL SELECT 'bom' table_name,COUNT(*) demo_count FROM bom WHERE created_by LIKE 'DEMO%'  OR bom_code LIKE 'DEMO%'  UNION ALL SELECT 'bom_version' table_name,COUNT(*) demo_count FROM bom_version WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'bom_component' table_name,COUNT(*) demo_count FROM bom_component WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'manufacturing_process' table_name,COUNT(*) demo_count FROM manufacturing_process WHERE created_by LIKE 'DEMO%'  OR process_code LIKE 'DEMO%'  UNION ALL SELECT 'routing' table_name,COUNT(*) demo_count FROM routing WHERE created_by LIKE 'DEMO%'  OR routing_code LIKE 'DEMO%'  UNION ALL SELECT 'routing_revision' table_name,COUNT(*) demo_count FROM routing_revision WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'routing_step' table_name,COUNT(*) demo_count FROM routing_step WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'production_plan' table_name,COUNT(*) demo_count FROM production_plan WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'work_order' table_name,COUNT(*) demo_count FROM work_order WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'finished_goods_lot' table_name,COUNT(*) demo_count FROM finished_goods_lot WHERE created_by LIKE 'DEMO%'  OR lot_no LIKE 'DEMO%'  UNION ALL SELECT 'request_receipt' table_name,COUNT(*) demo_count FROM request_receipt WHERE created_by LIKE 'DEMO%'  OR scope_key=SHA2('DEMO-TEMP-20261029',256) UNION ALL SELECT 'production_result' table_name,COUNT(*) demo_count FROM production_result WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'production_result_correction' table_name,COUNT(*) demo_count FROM production_result_correction WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'raw_material_lot' table_name,COUNT(*) demo_count FROM raw_material_lot WHERE created_by LIKE 'DEMO%'  OR lot_no LIKE 'DEMO%'  UNION ALL SELECT 'material_consumption' table_name,COUNT(*) demo_count FROM material_consumption WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'material_return' table_name,COUNT(*) demo_count FROM material_return WHERE created_by LIKE 'DEMO%'  UNION ALL SELECT 'quality_inspection' table_name,COUNT(*) demo_count FROM quality_inspection WHERE created_by LIKE 'DEMO%' ) existing_demo)=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: existing full or partial DEMO data; no merge','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='mini_mes' AND ENGINE='InnoDB')=18 AND (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='mini_mes')=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: schema/trigger mismatch','$')) AS seed_guard;
SET @item_base=(SELECT COALESCE(MAX(item_id),0) FROM item);
SET @bom_base=(SELECT COALESCE(MAX(bom_id),0) FROM bom);
SET @bom_version_base=(SELECT COALESCE(MAX(bom_version_id),0) FROM bom_version);
