SPECTION' AND payload_fingerprint=UNHEX(SHA2(CONCAT('QUALITY_INSPECTION:v1',CHAR(10),'finishedLotId=',CAST(@finished_goods_lot_base+2 AS UNSIGNED),CHAR(10),'inspectedQty=','50',CHAR(10),'acceptedQty=','49',CHAR(10),'rejectedQty=','1',CHAR(10),'inspectorRef=','10:DEMO-QC-01',CHAR(10),'judgementReason=','12:DEMO 최종 품질검사'),256)) AND JSON_CONTAINS(initial_outcome_snapshot,JSON_OBJECT('version',1,'inspectionId',CAST(@quality_inspection_base+3 AS UNSIGNED),'finishedLotId',CAST(@finished_goods_lot_base+2 AS UNSIGNED),'workOrderId',CAST(@work_order_base+2 AS UNSIGNED),'roundNo',1,'inspectedQty','50','acceptedQty','49','rejectedQty','1','inspectorRef','DEMO-QC-01','judgementReason','DEMO 최종 품질검사','inspectedAt','2026-10-28T06:00:00.000000Z')) AND JSON_LENGTH(initial_outcome_snapshot)=11)))=22),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: receipt fingerprint/snapshot mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM request_receipt r WHERE r.created_by=@demo_actor AND (r.processed_at IS NULL OR r.initial_outcome_snapshot IS NULL OR r.scope_key<>SHA2(@demo_actor,256) OR r.request_key NOT REGEXP '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR ((SELECT COUNT(*) FROM material_consumption c WHERE c.receipt_id=r.receipt_id)+(SELECT COUNT(*) FROM material_return x WHERE x.receipt_id=r.receipt_id)+(SELECT COUNT(*) FROM production_result p WHERE p.receipt_id=r.receipt_id)+(SELECT COUNT(*) FROM quality_inspection q WHERE q.receipt_id=r.receipt_id))<>1))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: receipt linkage mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM raw_material_lot l LEFT JOIN (SELECT raw_lot_id,SUM(consumed_qty) qty FROM material_consumption GROUP BY raw_lot_id)c ON c.raw_lot_id=l.raw_lot_id LEFT JOIN (SELECT c.raw_lot_id,SUM(r.returned_qty) qty FROM material_return r JOIN material_consumption c ON c.consumption_id=r.consumption_id GROUP BY c.raw_lot_id)x ON x.raw_lot_id=l.raw_lot_id WHERE l.created_by=@demo_actor AND l.available_qty<>l.registered_qty-COALESCE(c.qty,0)+COALESCE(x.qty,0))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: raw lot ledger mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM material_consumption c JOIN work_order w ON w.work_order_id=c.work_order_id JOIN raw_material_lot l ON l.raw_lot_id=c.raw_lot_id JOIN bom_component b ON b.bom_component_id=c.bom_component_id JOIN request_receipt r ON r.receipt_id=c.receipt_id WHERE c.created_by=@demo_actor AND (b.bom_version_id<>w.bom_version_id OR b.material_item_id<>l.item_id OR b.material_unit_code<>l.unit_code OR r.operation_code<>'MATERIAL_CONSUME' OR c.consumed_at<w.started_at OR (w.completed_at IS NOT NULL AND c.consumed_at>w.completed_at)))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: consumption BOM/time mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM material_consumption c LEFT JOIN (SELECT consumption_id,SUM(returned_qty)qty FROM material_return GROUP BY consumption_id)x ON x.consumption_id=c.consumption_id WHERE c.created_by=@demo_actor AND COALESCE(x.qty,0)>c.consumed_qty)=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: return exceeds original consumption','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM material_return x JOIN material_consumption c ON c.consumption_id=x.consumption_id JOIN work_order w ON w.work_order_id=c.work_order_id JOIN request_receipt r ON r.receipt_id=x.receipt_id WHERE x.created_by=@demo_actor AND (r.operation_code<>'MATERIAL_RETURN' OR x.returned_at<c.consumed_at OR (w.completed_at IS NOT NULL AND x.returned_at>w.completed_at)))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: return time/operation mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM work_order w JOIN production_plan p ON p.production_plan_id=w.production_plan_id JOIN bom_version v ON v.bom_version_id=w.bom_version_id JOIN bom b ON b.bom_id=v.bom_id JOIN routing_revision rr ON rr.routing_revision_id=w.routing_revision_id JOIN routing rt ON rt.routing_id=rr.routing_id WHERE w.created_by=@demo_actor AND (w.product_item_id<>p.product_item_id OR w.product_item_id<>b.product_item_id OR w.product_item_id<>rt.product_item_id OR v.first_used_at IS NULL OR rr.first_used_at IS NULL OR v.first_used_at>w.created_at OR rr.first_used_at>w.created_at))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: work order source mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM work_order w LEFT JOIN finished_goods_lot f ON f.work_order_id=w.work_order_id LEFT JOIN (SELECT finished_lot_id,COUNT(*)cnt,SUM(produced_qty)p,SUM(good_qty)g,SUM(defect_qty)b FROM production_result GROUP BY finished_lot_id)x ON x.finished_lot_id=f.finished_lot_id WHERE w.created_by=@demo_actor AND (COALESCE(x.p,0)>w.ordered_qty OR (w.status='COMPLETED' AND (COALESCE(x.cnt,0)=0 OR x.p<>w.ordered_qty OR x.p<>x.g+x.b OR x.g<>w.inspection_target_qty)) OR (w.status IN ('READY','CANCELLED') AND (f.finished_lot_id IS NOT NULL OR EXISTS(SELECT 1 FROM material_consumption c WHERE c.work_order_id=w.work_order_id)))))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: work order status/quantity mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM production_result p JOIN finished_goods_lot f ON f.finished_lot_id=p.finished_lot_id JOIN work_order w ON w.work_order_id=f.work_order_id JOIN request_receipt r ON r.receipt_id=p.receipt_id WHERE p.created_by=@demo_actor AND (r.operation_code<>'PRODUCTION_RESULT' OR p.produced_qty<=0 OR p.produced_at<w.started_at OR (w.completed_at IS NOT NULL AND p.produced_at>w.completed_at)))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: production time/operation mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM production_result_correction c JOIN production_result p ON p.production_result_id=c.production_result_id JOIN finished_goods_lot f ON f.finished_lot_id=p.finished_lot_id JOIN work_order w ON w.work_order_id=f.work_order_id JOIN request_receipt r ON r.receipt_id=p.receipt_id WHERE c.created_by=@demo_actor AND (c.to_revision<>p.revision_no OR c.after_produced_qty<>p.produced_qty OR c.after_good_qty<>p.good_qty OR c.after_defect_qty<>p.defect_qty OR c.created_at<p.produced_at OR c.created_at>w.completed_at OR JSON_UNQUOTE(JSON_EXTRACT(r.initial_outcome_snapshot,'$.goodQty'))<>CAST(c.before_good_qty AS UNSIGNED) OR c.before_produced_at<>p.produced_at OR c.after_produced_at<>p.produced_at OR c.before_worker_ref<>p.worker_ref OR c.after_worker_ref<>p.worker_ref))=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: correction chain mismatch','$')) AS seed_guard;
SELECT IF(((SELECT COUNT(*) FROM quality_inspection q JOIN finished_goods_lot f ON f.finished_lot_id=q.finished_lot_id JOIN work_order w ON w.work_order_id=f.work_order_id JOIN request_receipt r ON r.receipt_id=q.receipt_id WHERE q.created_by=@demo_actor AND (w.status<>'COMPLETED' OR q.inspected_at<w.completed_at OR q.inspected_qty<=0 OR r.operation_code<>'QUALITY_INSPECTION'))=0 AND (SELECT COUNT(*) FROM work_order w JOIN finished_goods_lot f ON f.work_order_id=w.work_order_id JOIN (SELECT finished_lot_id,SUM(inspected_qty) qty FROM quality_inspection GROUP BY finished_lot_id) q ON q.finished_lot_id=f.finished_lot_id WHERE w.created_by=@demo_actor AND q.qty>w.inspection_target_qty)=0),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: inspection target/time mismatch','$')) AS seed_guard;
SELECT IF(((SELECT SUM(produced_qty) FROM production_result WHERE created_by=@demo_actor)=190 AND (SELECT SUM(good_qty) FROM production_result WHERE created_by=@demo_actor)=180 AND (SELECT SUM(defect_qty) FROM production_result WHERE created_by=@demo_actor)=10),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: production totals mismatch','$')) AS seed_guard;
SELECT IF(((SELECT SUM(inspection_target_qty) FROM work_order WHERE created_by=@demo_actor)=151 AND (SELECT SUM(accepted_qty) FROM quality_inspection WHERE created_by=@demo_actor)=137 AND (SELECT SUM(rejected_qty) FROM quality_inspection WHERE created_by=@demo_actor)=6 AND (SELECT SUM(inspected_qty) FROM quality_inspection WHERE created_by=@demo_actor)=143),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: inspection totals mismatch','$')) AS seed_guard;
-- 생성식과 독립적으로 저장된 원장에서 Java Command의 정규화 payload를 재구성한다.
SELECT IF((
    (SELECT COUNT(*) FROM material_consumption c JOIN request_receipt r ON r.receipt_id=c.receipt_id
     WHERE c.created_by=@demo_actor AND r.payload_fingerprint<>UNHEX(SHA2(CONCAT(
         'MATERIAL_CONSUME:v1',CHAR(10),'workOrderId=',c.work_order_id,CHAR(10),
         'bomComponentId=',c.bom_component_id,CHAR(10),'rawLotId=',c.raw_lot_id,CHAR(10),
         'consumedQty=',CAST(c.consumed_qty AS UNSIGNED)),256)))=0
    AND (SELECT COUNT(*) FROM material_return x JOIN request_receipt r ON r.receipt_id=x.receipt_id
     WHERE x.created_by=@demo_actor AND r.payload_fingerprint<>UNHEX(SHA2(CONCAT(
         'MATERIAL_RETURN:v1',CHAR(10),'consumptionId=',x.consumption_id,CHAR(10),
         'returnedQty=',CAST(x.returned_qty AS UNSIGNED),CHAR(10),'reason=',x.reason),256)))=0
    AND (SELECT COUNT(*) FROM production_result p
     JOIN finished_goods_lot f ON f.finished_lot_id=p.finished_lot_id
     JOIN request_receipt r ON r.receipt_id=p.receipt_id
     LEFT JOIN production_result_correction c ON c.production_result_id=p.production_result_id AND c.from_revision=1
     WHERE p.created_by=@demo_actor AND r.payload_fingerprint<>UNHEX(SHA2(CONCAT(
         'PRODUCTION_RESULT:v1',CHAR(10),'workOrderId=',f.work_order_id,CHAR(10),
         IF(p.production_result_id=(SELECT MIN(x.production_result_id) FROM production_result x WHERE x.finished_lot_id=p.finished_lot_id),
             CONCAT('mode=FIRST',CHAR(10),'lotNo=',f.lot_no),'mode=EXISTING'),CHAR(10),
         'producedQty=',CAST(COALESCE(c.before_produced_qty,p.produced_qty) AS UNSIGNED),CHAR(10),
         'goodQty=',CAST(COALESCE(c.before_good_qty,p.good_qty) AS UNSIGNED),CHAR(10),
         'defectQty=',CAST(COALESCE(c.before_defect_qty,p.defect_qty) AS UNSIGNED),CHAR(10),
         'workerRef=',p.worker_ref),256)))=0
    AND (SELECT COUNT(*) FROM quality_inspection q JOIN request_receipt r ON r.receipt_id=q.receipt_id
     WHERE q.created_by=@demo_actor AND r.payload_fingerprint<>UNHEX(SHA2(CONCAT(
         'QUALITY_INSPECTION:v1',CHAR(10),'finishedLotId=',q.finished_lot_id,CHAR(10),
         'inspectedQty=',CAST(q.inspected_qty AS UNSIGNED),CHAR(10),
         'acceptedQty=',CAST(q.accepted_qty AS UNSIGNED),CHAR(10),
         'rejectedQty=',CAST(q.rejected_qty AS UNSIGNED),CHAR(10),
         'inspectorRef=',CHAR_LENGTH(q.inspector_ref),':',q.inspector_ref,CHAR(10),
         'judgementReason=',IF(q.judgement_reason IS NULL,'NULL',CONCAT(CHAR_LENGTH(q.judgement_reason),':',q.judgement_reason))),256)))=0
),'OK',JSON_EXTRACT('DEMO_SEED_ABORT: ledger-derived Java fingerprint mismatch','$')) AS seed_guard;
COMMIT;
SELECT RELEASE_LOCK('mini_mes.DEMO-TEMP-20261029') AS seed_lock_released;
SELECT 'COMMITTED' seed_result,@demo_actor demo_actor;
SELECT status,COUNT(*) order_count FROM work_order WHERE created_by=@demo_actor GROUP BY status;
SELECT SUM(produced_qty) produced,SUM(good_qty) good,SUM(defect_qty) defect FROM production_result WHERE created_by=@demo_actor;
SELECT SUM(inspected_qty) inspected,SUM(accepted_qty) accepted,SUM(rejected_qty) rejected FROM quality_inspection WHERE created_by=@demo_actor;
